/* E10 additions (23 September 2026): order-intake pause and waiting list.
 * Local sample behaviour only. No live customer records, sending or provider calls.
 * Loaded last. Adds A.intakePanel (Store setup), the #settings/waitlist page, an
 * owner-only banner, and lazy state enrichment (state.intake, state.waitlist). */
(() => {
 'use strict';
 const A=window.AdminUI;if(!A||!A.S||!window.StudioUI)return;
 const S=A.S,U=window.StudioUI,{esc,money,button,actions,pill,panel,facts,notice,select,textarea,check,details,link,modal,list}=A;
 const PUBLIC_KEY='aalishaanIntakeWaitlist';
 const frames={white:'White',black:'Black','antique-gold':'Antique Gold'};
 // Draft customer-facing copy. Owner approval is recorded in docs/content/new-strings.md (NS-12) before production use.
 const COPY={title:'We’re running at full capacity',body:'Thank you for the wonderful response. Every Aalishaan piece is printed and framed to order, and the studio is currently working through a large number of orders. To keep our promise on quality and delivery, we’ve paused new orders for a short while. Leave your email or mobile number and we’ll tell you the moment ordering reopens. Your bag will be waiting for you.',button:'Tell me when ordering reopens',success:'Thank you. We’ll be in touch as soon as ordering reopens.',subject:'Ordering is open again at Aalishaan Studio'};
 function seed(){const p=S.state.products;const bagOf=(n,frame,quantity=1)=>({title:p[n]?.title||'Sample artwork',slug:p[n]?.slug||'',frame,quantity});return [
  {id:'WL-1001',token:'demo-token-1001',name:'Priya Nair',email:'priya@example.test',phone:'',at:'2026-09-13T04:10:00Z',source:'Checkout',bag:[bagOf(0,'black')],consent:{kind:'Service notification',wording:'waitlist-v1'},notice:null},
  {id:'WL-1002',token:'demo-token-1002',name:'',email:'',phone:'Sample phone 07',at:'2026-09-13T05:25:00Z',source:'Cart',bag:[bagOf(1,'antique-gold')],consent:{kind:'Service notification',wording:'waitlist-v1'},notice:null},
  {id:'WL-1003',token:'demo-token-1003',name:'Dev Malhotra',email:'dev@example.test',phone:'Sample phone 08',at:'2026-09-13T06:40:00Z',source:'Checkout',bag:[bagOf(2,'white'),bagOf(3,'black',2)],consent:{kind:'Service notification',wording:'waitlist-v1'},notice:null}
 ];}
 function ensure(){const s=S.state;if(!s.intake)s.intake={status:'Open',reason:'',note:'',since:null,resumed:null,history:[]};if(!Array.isArray(s.waitlist))s.waitlist=seed();return s;}
 function previewEntries(){try{const rows=JSON.parse(localStorage.getItem(PUBLIC_KEY)||'[]');return Array.isArray(rows)?rows.filter(r=>r&&typeof r==='object'):[];}catch{return [];}}
 const paused=()=>ensure().intake.status==='Paused';
 const when=iso=>iso?new Date(iso).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'Not recorded';
 const bagText=bag=>(Array.isArray(bag)?bag:[]).filter(i=>i&&typeof i==='object').map(i=>esc(i.title)+' / '+esc(frames[i.frame]||i.frame)+(i.quantity>1?' x '+i.quantity:'')).join('<br>')||'<small>No bag recorded</small>';
 const contact=e=>[e.name?esc(e.name):'',e.email?esc(e.email):'',e.phone?esc(e.phone):''].filter(Boolean).join('<br>')||'<small>No contact recorded</small>';
 const pending=()=>ensure().waitlist.filter(e=>e.email&&!e.notice);
 function stateStrip(){const i=ensure().intake,n=S.state.waitlist.length+previewEntries().length;return facts([['Order intake',pill(i.status==='Paused'?'Paused at capacity':'Open',i.status==='Paused'?'warn':'')],['Since',i.status==='Paused'?esc(when(i.since)):(i.resumed?'Reopened '+esc(when(i.resumed)):'No pause recorded')],['Reason',esc(i.reason||'—')+(i.note?`<br><small>${esc(i.note)}</small>`:'')],['Waiting',String(n)+' contact'+(n===1?'':'s')+' · '+link('settings/waitlist','Open the waiting list')]]);}
 A.intakePanel=()=>{if(S.state.role!=='owner')return '';const i=ensure().intake;return panel('Order intake',stateStrip()+`<p class="small">While intake is paused the public bag and checkout replace the payment step with a capacity notice and a waiting-list form (email or mobile, name optional). Paid orders, webhooks and production continue unchanged. Preview the customer view: <a href="../pages/cart/index.html?intake=paused" target="_blank" rel="noopener">bag</a> / <a href="../pages/checkout/index.html?intake=paused" target="_blank" rel="noopener">checkout</a>.</p>`+actions(i.status==='Paused'?button('intake-resume','Resume ordering',{},'button'):button('intake-pause','Pause order intake',{},'button danger'),link('settings/waitlist','Waiting list','button secondary'))+details('Pause history',i.history.length?list(i.history.map(h=>esc(h.action)+' · '+esc(when(h.at))+' · '+esc(h.actor)+(h.reason?' · '+esc(h.reason):'')+(h.note?' · '+esc(h.note):''))):'<p class="small">No pause recorded in this browser.</p>'),'An emergency control. Stops new public orders and collects a waiting list instead.');};
 A.handlers['intake-pause']=()=>{S.guard('settings');ensure();if(paused())throw Error('Order intake is already paused.');modal('Pause order intake?','New public orders stop immediately. Customers see the capacity notice and can join the waiting list. Existing orders, payments in flight and production are not affected.',select('reason','Reason',['Capacity reached','Studio closure','Other'])+textarea('note','Note for the activity record','',false)+check('confirm','I understand the public bag and checkout will stop accepting orders until intake is resumed'),d=>{if(!d.confirm)throw Error('Confirm the pause before continuing.');S.mutate('INTAKE','Pause order intake',()=>{const i=ensure().intake;i.status='Paused';i.reason=d.reason;i.note=d.note.trim();i.since=S.now();i.history.unshift({at:i.since,action:'Paused',reason:d.reason,note:d.note.trim(),actor:S.names[S.state.role]});},d.note.trim()||d.reason);},'Pause order intake',true);};
 A.handlers['intake-resume']=()=>{S.guard('settings');ensure();if(!paused())throw Error('Order intake is already open.');const n=pending().length;modal('Resume ordering?','The public bag and checkout accept orders again. Reopening notices go only to waiting-list contacts with an email address; phone-only contacts are listed for manual follow-up.',check('notify','Send the reopening notice now to '+n+' waiting contact'+(n===1?'':'s')+' with an email address',n>0)+textarea('note','Note for the activity record','',false),d=>{if(d.notify&&S.state.paused)throw Error('Milestone follow-ups are paused in Connections. Resume them first, or reopen without sending notices.');S.mutate('INTAKE','Resume order intake',()=>{const i=ensure().intake;i.status='Open';i.resumed=S.now();i.history.unshift({at:i.resumed,action:'Resumed',note:d.note.trim(),actor:S.names[S.state.role]});if(d.notify)sendNotices();},d.note.trim()||'Ordering resumed');},'Resume ordering');};
 function sendNotices(){const at=S.now();for(const e of pending())e.notice={status:'Provider accepted',attempts:1,at,template:'ordering-reopened-v1',subject:COPY.subject};}
 A.handlers['intake-notify']=()=>{S.guard('settings');ensure();const rows=pending();modal('Send reopening notices?','One service email per waiting contact, sent once. Contacts without an email address are not messaged from here.',rows.length?list(rows.map(e=>esc(e.email)+' · '+esc(e.source)+' · '+esc(when(e.at)))):notice('No eligible contacts','Every contact with an email address has already been notified, or none was recorded.'),()=>{if(paused())throw Error('Resume order intake before sending reopening notices.');if(S.state.paused)throw Error('Milestone follow-ups are paused in Connections. Resume them before sending.');if(!rows.length)throw Error('There is nothing to send.');S.mutate('WAITLIST','Send reopening notices',()=>sendNotices(),rows.length+' notice(s)');},'Send '+rows.length+' notice'+(rows.length===1?'':'s'));};
 A.handlers['intake-remove']=({id})=>{S.guard('settings');const e=ensure().waitlist.find(x=>x.id===id);if(!e)throw Error('Waiting-list entry not found.');modal('Remove this waiting-list entry?','Removal is recorded. Use it for a customer request or when the retention period has passed.',textarea('reason','Reason'),d=>S.mutate('WAITLIST','Remove waiting-list entry',()=>{S.state.waitlist=S.state.waitlist.filter(x=>x.id!==id);},d.reason),'Remove entry',true);};
 A.screens['settings/waitlist']=()=>{const s=ensure(),rows=s.waitlist,preview=previewEntries();const table=U.dataTable('Waiting list',['Contact','Bag','Joined','Consent','Reopening notice','Actions'],rows.map(e=>({id:e.id,cells:[contact(e)+`<small>${esc(e.id)}</small>`,bagText(e.bag),esc(when(e.at))+`<small>${esc(e.source)}</small>`,esc(e.consent?.kind||'Service notification')+`<small>${esc(e.consent?.wording||'')}</small>`,e.notice?pill(e.notice.status,e.notice.status==='Provider accepted'?'':'warn')+`<small>${esc(when(e.notice.at))}</small>`:e.email?pill('Not sent','neutral'):pill('Manual contact','neutral'),button('intake-remove','Remove',{id:e.id},'button secondary small-button')]})));
  const previewTable=preview.length?details('Captured in this browser’s storefront preview ('+preview.length+')',`<p class="small">Entries the public bag or checkout saved in this browser while the capacity notice was shown. Read-only here; clear them from the website’s Cookies page.</p>`+U.dataTable('Storefront preview entries',['Contact','Bag','Joined','Source'],preview.map((e,n)=>({id:'preview-'+n,cells:[contact(e),bagText(e.bag),esc(when(e.at)),esc(e.source||'Storefront')]})))):'';
  return A.heading('Waiting list','Contacts who asked to be told when ordering reopens.',stateStrip()+table+previewTable+details('Customer-facing copy (draft; owner approval needed)',`<div class="intake-copy"><p class="eyebrow">Bag and checkout notice</p><h3>${esc(COPY.title)}</h3><p>${esc(COPY.body)}</p><p><strong>Button:</strong> ${esc(COPY.button)}</p><p><strong>After joining:</strong> ${esc(COPY.success)}</p><p class="eyebrow">Reopening email</p><p><strong>Subject:</strong> ${esc(COPY.subject)}</p><p>One service message, sent once; the restore-your-bag link in it is single-use. No marketing content.</p></div>`)+notice('Retention and consent','Joining the list is a service notification, not marketing permission. Entries are removed once ordering reopens and the notice is sent, or after 90 days, whichever is first (D-37 lean, owner to confirm). Phone numbers are for manual contact only; no SMS or WhatsApp is sent automatically.'),actions(button('intake-notify','Send reopening notices',{},'button'),paused()?button('intake-resume','Resume ordering',{},'button secondary'):button('intake-pause','Pause order intake',{},'button secondary'),link('settings/rules','Store setup','button secondary')));};
 // Owner-only banner while intake is paused.
 const previousAfter=A.afterRender;A.afterRender=function(...args){if(previousAfter)previousAfter.apply(this,args);const main=document.getElementById('main');if(!main||!S.state.signedIn||S.state.role!=='owner')return;ensure();if(!paused())return;const n=S.state.waitlist.length+previewEntries().length;main.insertAdjacentHTML('afterbegin',`<div class="intake-banner" role="status"><span><strong>Order intake paused</strong> since ${esc(when(S.state.intake.since))} · ${n} waiting</span><span class="intake-banner-actions"><a class="text-link" href="#settings/waitlist">Waiting list</a><a class="text-link" href="#settings/rules">Manage</a></span></div>`);};
 // A scenario restart resets demo orders, customers, cases and messages; the intake state and waiting list are store settings and are kept, like the catalogue and staff records. A backup restore without them re-seeds the samples lazily.
 const startScenario=window.StudioState?.startScenario;if(startScenario)window.StudioState.startScenario=function(n){const keep=S.clone({intake:ensure().intake,waitlist:S.state.waitlist});const s=startScenario(n);S.state.intake=keep.intake;S.state.waitlist=keep.waitlist;S.save();return s;};
 const enrich=window.StudioState?.enrichProducts;if(enrich)window.StudioState.enrichProducts=function(){enrich();ensure();};
 ensure();
 window.StudioIntake={COPY,ensure,paused,previewEntries,PUBLIC_KEY};
})();
